<style>
@page { margin: 26px 30px; }
body { margin:0; font-family:DejaVu Sans,Arial,sans-serif; font-size:9px; line-height:1.45; color:#172033; background:#f6f8fb; }
.report-shell { width:100%; }
.report-header { margin:0 0 14px; padding:12px 14px; border:1px solid #dfe5ee; border-radius:12px; background:#fff; }
.report-header-table { width:100%; border-collapse:collapse; }
.report-brand-cell { width:55%; vertical-align:middle; }
.report-meta-cell { width:45%; vertical-align:middle; text-align:right; }
.brand { margin:0; font-size:16px; line-height:1.1; font-weight:700; letter-spacing:.35px; color:#172033; }
.brand-subtitle { margin-top:3px; font-size:6.5px; line-height:1; font-weight:700; letter-spacing:1px; color:#8a96a8; }
.report-type { display:inline-block; padding:4px 7px; border:1px solid #d9e4f7; border-radius:999px; background:#f4f8ff; color:#315fbd; font-size:7.5px; font-weight:700; }
.report-meta { margin-top:5px; font-size:7.2px; color:#8a96a8; }
.section { margin:0 0 12px; padding:11px 12px 12px; border:1px solid #dfe5ee; border-radius:11px; background:#fff; page-break-inside:avoid; }
.section-title { margin:0 0 3px; padding:0 0 0 7px; border-left:3px solid #315fbd; font-size:11px; line-height:1.25; color:#172033; font-weight:700; }
.section-subtitle { margin:0 0 8px 10px; font-size:7.7px; line-height:1.4; color:#8792a4; }
.metric-table { width:100%; border-collapse:separate; border-spacing:5px; margin:-3px -5px -4px; }
.metric-cell { width:25%; padding:8px; border:1px solid #e2e8f0; border-radius:8px; background:#f8fafc; vertical-align:top; }
.metric-label { font-size:6.8px; color:#718096; text-transform:uppercase; letter-spacing:.35px; font-weight:700; }
.metric-value { margin-top:3px; font-size:15px; line-height:1.1; font-weight:700; color:#172033; }
.metric-note { margin-top:3px; font-size:7px; line-height:1.35; color:#8a96a8; }
.blue{color:#315fbd}.green{color:#18804b}.amber{color:#a36b00}.purple{color:#6957c9}
.report-table { width:100%; border-collapse:collapse; margin-top:6px; }
.report-table th { padding:5px 6px; border-top:1px solid #e4e9f0; border-bottom:1px solid #d9e0ea; background:#f6f8fb; font-size:6.8px; font-weight:700; text-align:left; color:#61708a; text-transform:uppercase; letter-spacing:.25px; }
.report-table td { padding:5px 6px; border-bottom:1px solid #edf0f4; font-size:7.8px; vertical-align:top; }
.report-table tr:last-child td{border-bottom:none}.number{text-align:right;font-weight:700}
.status-row{width:100%;border-collapse:collapse;margin-top:3px}.status-row td{padding:5px 6px;border-bottom:1px solid #edf0f4;font-size:7.8px}.status-row tr:last-child td{border-bottom:none}.status-row td:last-child{text-align:right;font-weight:700}
.two-column{width:100%;border-collapse:separate;border-spacing:7px 0;margin:0 -7px}.two-column-cell{width:50%;vertical-align:top}
.empty{margin-top:6px;padding:10px;border:1px dashed #dfe5ee;border-radius:8px;background:#fafbfd;text-align:center;font-size:7.8px;color:#8a96a8}
.report-footer{margin-top:14px;padding-top:7px;border-top:1px solid #dfe5ee;font-size:6.8px;color:#8a96a8;text-align:center}
.page-break{page-break-before:always}.muted{color:#7b8799}.task-title{font-weight:700}.task-meta{color:#7b8799;font-size:6.8px;margin-top:2px}
.badge{display:inline-block;padding:2px 5px;border-radius:8px;background:#f1f5fb;color:#526078;font-size:6.8px}.badge-amber{background:#fff5df;color:#a36b00}.badge-green{background:#ecfdf3;color:#18804b}
.report-divider{height:1px;background:#edf0f4;margin:0 0 10px}
</style>
